sys_script_client.script:
function onSubmit() {

    // --------------------------------------------------
    // 1. Mandatory field validation
    // --------------------------------------------------

    if (!g_form.getValue('patient')) {
        g_form.addErrorMessage('Patient is required.');
        return false;
    }

    if (!g_form.getValue('admission')) {
        g_form.addErrorMessage('Admission is required.');
        return false;
    }

    if (!g_form.getValue('handoff_type')) {
        g_form.addErrorMessage('Handoff Type is required.');
        return false;
    }

    if (!g_form.getValue('from_department')) {
        g_form.addErrorMessage('From Department is required.');
        return false;
    }

    if (!g_form.getValue('handoff_date')) {
        g_form.addErrorMessage('Handoff Date is required.');
        return false;
    }

    if (!g_form.getValue('handed_over_by')) {
        g_form.addErrorMessage('Handed Over By is required.');
        return false;
    }

    if (!g_form.getValue('received_by')) {
        g_form.addErrorMessage('Received By is required.');
        return false;
    }

    if (!g_form.getValue('handoff_notes')) {
        g_form.addErrorMessage('Handoff Notes are required.');
        return false;
    }


    // --------------------------------------------------
    // 2. Handed Over By and Received By validation
    // --------------------------------------------------

    if (g_form.getValue('handed_over_by') ==
        g_form.getValue('received_by')) {

        g_form.addErrorMessage(
            'Handed Over By and Received By must be different users.'
        );

        return false;
    }


    // --------------------------------------------------
    // 3. Department validation
    // --------------------------------------------------

    if (g_form.getValue('to_department') &&
        g_form.getValue('to_department') ==
        g_form.getValue('from_department')) {

        g_form.addErrorMessage(
            'To Department must be different from From Department.'
        );

        return false;
    }


    // --------------------------------------------------
    // 4. Ward validation
    // --------------------------------------------------

    if (g_form.getValue('from_ward') &&
        g_form.getValue('to_ward') &&
        g_form.getValue('from_ward') ==
        g_form.getValue('to_ward')) {

        g_form.addErrorMessage(
            'To Ward must be different from From Ward.'
        );

        return false;
    }


    // --------------------------------------------------
    // 5. Bed validation
    // --------------------------------------------------

    if (g_form.getValue('from_bed') &&
        g_form.getValue('to_bed') &&
        g_form.getValue('from_bed') ==
        g_form.getValue('to_bed')) {

        g_form.addErrorMessage(
            'To Bed must be different from From Bed.'
        );

        return false;
    }


    // --------------------------------------------------
    // 6. Handoff Type validation
    // --------------------------------------------------

    var handoffType = g_form.getValue('handoff_type');

    if (handoffType == 'Department Transfer' &&
        !g_form.getValue('to_department')) {

        g_form.addErrorMessage(
            'To Department is required for a Department Transfer.'
        );

        return false;
    }

    if (handoffType == 'Ward Transfer' &&
        !g_form.getValue('to_ward')) {

        g_form.addErrorMessage(
            'To Ward is required for a Ward Transfer.'
        );

        return false;
    }


    // --------------------------------------------------
    // 7. Handoff Status validation
    // --------------------------------------------------

    var handoffStatus = g_form.getValue('handoff_status');

    if ((handoffStatus == 'Completed' ||
         handoffStatus == 'Cancelled') &&
        !g_form.getValue('handoff_notes')) {

        g_form.addErrorMessage(
            'Handoff Notes are required when Handoff Status is Completed or Cancelled.'
        );

        return false;
    }


    // --------------------------------------------------
    // All validations passed
    // --------------------------------------------------

    return true;
}
